// Un item por correo pendiente, con el workflow del banco que debe procesarlo
const banks = $('Bancos').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const out = [];
res.forEach((r, i) => {
  for (const m of (r.messages || [])) out.push({ json: { id: m.id, threadId: m.threadId, workflowId: banks[i].workflowId, banco: banks[i].banco } });
});
return out;

// Reprocesa correos concretos en el workflow de su banco (mismo camino que el repartidor), sin tocar etiquetas de Gmail.
// POST {"messages":[{"id":"<gmail id>","banco":"Ibercaja_Offers_Received"}]} con cabecera x-offers-secret.
const BANKS = {"YqQIDjAozwsDAQR1": "CRSur_Offers_Received", "d3S1y48F0qKoVc6O": "Bankinter_Offers_Received_v19", "IOIg26EPCqtgCSLv": "CRAragón_Offers_Received", "12m8gBooQnUpwG14": "CRAsturias_Offers_Received", "Yd82lkDzorla4x7T": "CRGranada_Offers_Received", "eoxXdCBbq6zFL2me": "CRTeruel_Offers_Received_v3", "RezivFIqH10FdaB9": "CaixaBank_Offers_Received", "O6V1P2efIYpyu1bC": "CaixaPopular_Offers_Received_v2", "sEQ8HDbHIB3HvPDY": "DeutscheBank_Offers_Received", "qXIKYBEK2Yr7LWWs": "EuroCajaRural_Offers_Received", "n35da7vAodC9XUsH": "Globalcaja_Offers_Received", "IZpYM4yNvwza5ol7": "ING_Offers_Received", "VI1n8UQng6gAWV8B": "Ibercaja_Offers_Received", "iMzC4NjXDOlCbPuf": "LaboralKutxa_Offers_Received", "mxewpxzScRz3jHX2": "MyInvestor_Offers_Received_v2", "ZtErLRcQa0SwXfZb": "Sabadell_Offers_Received_v1", "pNOk4VBlVu9PLdKV": "UCI_Offers_Received", "hY2DR1im7zSNx28E": "Unicaja_Offers_Received_v4"};
const req = $input.first().json;
if ((req.headers || {})['x-offers-secret'] !== $vars.OFFERS_API_SECRET) throw new Error('Unauthorized: secreto inválido');
const byName = Object.fromEntries(Object.entries(BANKS).map(([id, n]) => [n.toLowerCase(), id]));
const list = Array.isArray(req.body?.messages) ? req.body.messages : [];
const out = [];
for (const m of list.slice(0, 20)) {
  const id = String(m.id || '').trim();
  const workflowId = BANKS[m.workflowId] ? m.workflowId : byName[String(m.banco || '').toLowerCase()];
  if (!/^[0-9a-f]{12,20}$/i.test(id) || !workflowId) throw new Error('Correo o banco no válido: ' + JSON.stringify(m));
  out.push({ json: { id, threadId: m.threadId || id, workflowId, banco: BANKS[workflowId], reprocesado: true } });
}
if (!out.length) throw new Error('Sin correos que reprocesar');
return out;
